let autoSaveTimer=0,autoSaveKinds=new Set(),autoSaveReady=false;
function setAutoSaveState(text){const el=$('autoSaveState');if(el)el.textContent=text}
function scheduleAutoSave(kind){if(!autoSaveReady||!kind)return;autoSaveKinds.add(kind);clearTimeout(autoSaveTimer);autoSaveTimer=setTimeout(()=>{flushAutoSave().catch(()=>{})},700)}
async function flushAutoSave(){const kinds=new Set(autoSaveKinds);autoSaveKinds.clear();autoSaveTimer=0;if(!kinds.size)return;setAutoSaveState('در حال ذخیره…');try{if(kinds.has('settings'))await saveSettings({silent:true});if(kinds.has('connections'))await saveConnections({silent:true});if(kinds.has('profile'))await saveProfile(false,true,{silent:true});setAutoSaveState('ذخیره شد')}catch{setAutoSaveState('ذخیره نشد')}}
