function chatDate(value){if(!value)return'—';const date=new Date(value);if(Number.isNaN(date.getTime()))return String(value);try{return new Intl.DateTimeFormat('fa-IR',{dateStyle:'medium',timeStyle:'short'}).format(date)}catch{return date.toLocaleString()}}
function wireBasalamChatModal(){const root=$('resultModal');if(!root)return;root.onclick=async event=>{if(event.target===root||event.target.closest('[data-modal-action="close"]'))return root.remove();const action=event.target.closest('[data-chat-action]')?.dataset.chatAction;if(action==='refresh')return openBasalamChats(true);if(action==='all'||action==='unseen'){basalamChatState.filter=action;return renderBasalamChats()}if(action==='back')return renderBasalamChats();if(action==='open'){const id=Number(event.target.closest('[data-chat-id]')?.dataset.chatId);if(id)await openBasalamChatDetail(id)}};root.oninput=event=>{const input=event.target.closest('[data-chat-search]');if(input){basalamChatState.query=input.value;renderBasalamChats();requestAnimationFrame(()=>$('resultModal')?.querySelector('[data-chat-search]')?.focus())}}}
