function aiTab(name){document.querySelectorAll('[data-ai-tab]').forEach(x=>x.classList.toggle('active',x.dataset.aiTab===name));document.querySelectorAll('[data-ai-panel]').forEach(x=>x.classList.toggle('active',x.dataset.aiPanel===name));if(name==='agent')loadAgentTab();if(name==='chat')loadChatTab()}function agentSubTab(name){document.querySelectorAll('[data-agent-sub]').forEach(x=>x.classList.toggle('active',x.dataset.agentSub===name));document.querySelectorAll('.agent-subpanel').forEach(x=>x.classList.toggle('active',x.id==='agentSub'+name.charAt(0).toUpperCase()+name.slice(1)));if(name==='guide')loadWorkersCatalog()}
