function aiModelDisplay(model,provider=null){const endpoint=aiDedicatedEndpoint(model),reasoning=provider&&aiReasoningModel(provider,model);return String(model)+(endpoint?' · '+endpoint+' اختصاصی':reasoning?' · استدلالی':'')}
